#include <iostream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<double> probabilities(n);
    for (int i = 0; i < n; ++i) {
        cin >> probabilities[i];
    }

    vector<double> result(n, 0.0);
    vector<double> dynamic(1 << n, 0.0);
    vector<double> sum_mask(1 << n, 0.0);

    auto countSetBits = [](int x) {
        int count = 0;
        while (x) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    };

    for (int mask = 0; mask < (1 << n); ++mask) {
        double s = 0.0;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i))
                s += probabilities[i];
        }
        sum_mask[mask] = s;
    }

    dynamic[0] = 1.0;
    int flag = 0;

    for (int mask = 0; mask < (1 << n); ++mask) {
        int count_bits_mask = countSetBits(mask);
        if (count_bits_mask > k) continue;
        if (dynamic[mask] < 1e-100) continue;
        if (count_bits_mask == k) flag = 1;
        double remaining_sum = 1.0 - sum_mask[mask];
        if (remaining_sum < 1e-6) continue;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            double prob_move = dynamic[mask] * probabilities[i] / remaining_sum;
            dynamic[mask | (1 << i)] += prob_move;
        }
    }

    if (flag == 0) {
        for (int i = 0; i < n; ++i) {
            result[i] = (probabilities[i] < 1e-6) ? 0.0 : 1.0;
        }
    } else {
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (countSetBits(mask) == k) {
                for (int i = 0; i < n; ++i) {
                    if (mask & (1 << i))
                        result[i] += dynamic[mask];
                }
            }
        }
    }

    cout << fixed << setprecision(12);
    for (int i = 0; i < n; ++i) {
        if (i > 0) cout << " ";
        cout << result[i];
    }
    cout << "\n";

    return 0;
}
